/// <summary>
/// Scans batch monitoring log records with status Running and marks records as Failed
/// for any session that is no longer active.
/// </summary>
public class METBatchMonitoringLogUpdateSessionStatus extends RunBaseBatch implements BatchRetryable
{
    QueryRun    queryRun;

    #define.CurrentVersion(1)

}

Method.Source:
public boolean unpack(container _packedClass)
{
    Version    version = RunBase::getVersion(_packedClass);
    container  queryCon;
    switch (version)
    {
        case #CurrentVersion:
            [version, queryCon] = _packedClass;
            if (SysQuery::isPackedOk(queryCon))
            {
                queryRun = new QueryRun(queryCon);
            }
            else
            {
                this.initQuery();
            }
            break;
        default:
            return false;
    }
    return true;
}

public void run()
{
    METBatchMonitoringLog   log;
    int                     updatedCount;
    RecId                   logRecId;

    while (queryRun.next())
    {
        log = queryRun.get(tablenum(METBatchMonitoringLog));

        if (!log.isSessionActive())
        {
            logRecId = log.RecId;
            ttsbegin;
            select forupdate log
                where log.RecId == logRecId;
            log.Status = METBatchMonitoringStatus::Failed;
            log.update();
            ttscommit;
            updatedCount++;
        }
    }

    info(strFmt("@MET:METBatchMonitoringUpdateSessionStatusResult", updatedCount));
}

public void initQuery()
{
    Query                   query = new Query();
    QueryBuildDataSource    qbds = query.addDataSource(tablenum(METBatchMonitoringLog));
    QueryBuildRange         qBR;
    ;
    qBR = SysQuery::findOrCreateRange(qbds, fieldnum(METBatchMonitoringLog, Status));
    qBR.value(queryValue(METBatchMonitoringStatus::Running));
    qBR.status(RangeStatus::HIDDEN);

    queryRun = new QueryRun(query);
}

public static METBatchMonitoringLogUpdateSessionStatus construct()
{
    return new METBatchMonitoringLogUpdateSessionStatus();
}

public static void main(Args _args)
{
    METBatchMonitoringLogUpdateSessionStatus runObject = METBatchMonitoringLogUpdateSessionStatus::construct();
    ;
    if (runObject.prompt())
    {
        runObject.runOperation();
    }
}
